import React, {useContext} from 'react';
import {Context} from "../../index";
import Modal from 'react-bootstrap/Modal';
import Form from 'react-bootstrap/Form';
import Button from 'react-bootstrap/Button';
import DropDown from 'react-bootstrap/DropDown';
import DropdownMenu from 'react-bootstrap/esm/DropdownMenu';
import DropdownItem from 'react-bootstrap/esm/DropdownItem';
import Row from 'react-bootstrap/esm/Row';
import Col from 'react-bootstrap/esm/Col';



const CreateDish = ({show, onHide}) => {
    const {dish} = useContext(Context)
    const [info, setInfo] = useState ([])

    const addInfo= () => {
        setInfo([...info, {title: '', description:'', number: Date.now()}])
    }

    return(
        <Modal
            show={show}
            onHide={onHide}
            size="lg"
            aria-labelledby="contained-modal-title-vcenter"
            centered
        >
        <Modal.Header closeButton>
            <Modal.Title id="contained-modal-title-vcenter">
                Додати товар
            </Modal.Title>
        </Modal.Header>
        <Modal.Body>
            <Form>
               <DropDown>
                    <DropDown.Toggle>Оберіть тип товару</DropDown.Toggle>
                    <DropdownMenu>
                        {dish.types.map(type =>
                            <DropdownItem key={type.id}>{type.name}</DropdownItem>
                        )}
                    </DropdownMenu>
               </DropDown>
               <Form.Control className='mt-3'
                    placeholder='Назва товару...'
               />
               <Form.Control className='mt-3'
                    placeholder='Ціна товару...'
                    type='number'
               />
               <Form.Control className='mt-3'
                    type='file'
               />
               <hr/>
               <Button variant='outline-dark' onClick={addInfo}>Додати склад</Button>
               {info.map(i =>
                    <Row>
                        <Col md={4}>
                            <Form.Control>
                                placeholder="Введіть назву"
                            </Form.Control>
                        </Col>
                        <Col md={4}>
                            <Form.Control>
                            placeholder="Введіть опис"
                            </Form.Control>
                        </Col>
                    </Row>
                )}
            </Form>
        </Modal.Body>
        <Modal.Footer>
            <Button variant='outline-danger' onClick={onHide}>Закрити</Button>
            <Button variant='outline-success' onClick={onHide}>Додати</Button>
        </Modal.Footer>
    </Modal>
    )
}

export default CreateDish;
